    assert_eq!(output[COMPLETED], 0);
    assert_eq!(output[FAILED], 1);
}

fn assert_rejected(cwd: &Path, report: &str, message: &str) {
    let output = run(cwd, verify_command(report));
    assert_eq!(output.status.code(), Some(2));
    let json = serde_json::from_slice::<JsonValue>(&output.stdout).unwrap();
    assert_eq!(json["accepted"], false);
    let actual = json["message"].as_str().unwrap();
    assert!(
        actual.contains(message),
        "expected rejection containing {message:?}, got {actual:?}"
    );
}

