use std::ffi::OsStr;
use std::path::Path;

use serde_json::{json, Value as JsonValue};

use crate::support::{run, stage_put_cid, verify_stage_json, write_json};

pub(super) fn put_and_assert(cwd: &Path, observation: &str, accepted: bool) -> String {
    let stage = put_stage(cwd, observation, accepted);
    assert_existing(cwd, &stage, accepted);
    stage
}

pub(super) fn assert_existing(cwd: &Path, stage: &str, accepted: bool) {
    let output = if accepted {
        verify_stage_json(cwd, &stage)
    } else {
        let result = run(
            cwd,
            [
                OsStr::new("stage"),
                OsStr::new("verify"),
                OsStr::new(stage),
                OsStr::new("--format"),
                OsStr::new("json"),
            ],
        );
        assert_eq!(result.status.code(), Some(2));
        serde_json::from_slice::<JsonValue>(&result.stdout).unwrap()
    };
    assert_eq!(output["accepted"], accepted);
    assert_eq!(output["acceptance"]["checked"], 1);
    assert_eq!(output["acceptance"]["failed"], usize::from(!accepted));
    let verified = &output["acceptance"]["foreign_process_execution_observations"][0];
    assert_eq!(verified["accepted"], accepted);
    assert_eq!(verified["observation_cid_is_authority"], false);
    assert_eq!(verified["observation_cid_is_currentness"], false);
    assert_eq!(verified["grants_call_execution_authority"], false);
    assert_eq!(verified["grants_activation_authority"], false);
    assert_eq!(verified["grants_effect_authority"], false);
    assert_eq!(verified["grants_state_mutation_authority"], false);
    assert_eq!(verified["default_deployed"], false);
    if accepted {
        assert_eq!(verified["execution_observation_cid"], observation);
    }
}

